<script setup lang="ts">import{computed,ref}from'vue';import{useI18n}from'vue-i18n';import PageHeader from'@/components/PageHeader.vue';import{projects,skills,colleagues,connectors,discoverItems,libraryFiles}from'@/data/mock';const props=defineProps<{kind:string}>();const{t}=useI18n();const search=ref('');const title=computed(()=>t(`nav.${props.kind}`));const data=computed(()=>props.kind==='projects'?projects:props.kind==='skills'?skills:props.kind==='colleagues'?colleagues:props.kind==='connectors'?connectors:props.kind==='discover'?discoverItems:libraryFiles);const filtered=computed(()=>data.value.filter((x:any)=>JSON.stringify(x).toLowerCase().includes(search.value.toLowerCase())))</script><template><section class="flex min-w-0 flex-1 flex-col overflow-hidden"><PageHeader :title="title" :description="t(`page.${kind}`)"><div class="flex gap-2"><UInput v-if="kind==='skills'||kind==='library'" v-model="search" icon="i-lucide-search" :placeholder="t('common.search')"/><UButton v-else-if="kind==='projects'||kind==='colleagues'" icon="i-lucide-plus" :label="t('common.new')"/></div></PageHeader><div class="flex-1 overflow-y-auto p-6"><div v-if="kind==='library'" class="overflow-hidden rounded-xl border border-default"><table class="w-full text-left text-sm"><thead class="bg-muted text-muted"><tr><th class="p-3">名称</th><th class="p-3">来源</th><th class="p-3">大小</th><th class="p-3">更新时间</th></tr></thead><tbody><tr v-for="f in filtered" :key="(f as any).id" class="border-t border-default"><td class="p-3 font-medium">{{(f as any).name}}</td><td class="p-3 text-muted">{{(f as any).from}}</td><td class="p-3 text-muted">{{(f as any).size}}</td><td class="p-3 text-muted">{{(f as any).updatedAt}}</td></tr></tbody></table></div><div v-else class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><component :is="kind==='projects'?'RouterLink':'article'" v-for="item in filtered" :key="(item as any).id" :to="kind==='projects'?`/projects/${(item as any).id}`:undefined"><UCard class="h-full hover:bg-elevated"><div class="flex items-start gap-3"><span class="flex size-11 shrink-0 items-center justify-center rounded-xl bg-muted text-xl">{{(item as any).emoji}}</span><div class="min-w-0 flex-1"><div class="flex items-center gap-2"><b class="text-sm">{{(item as any).name||(item as any).title}}</b><UBadge v-if="(item as any).tag" size="xs">{{(item as any).tag}}</UBadge></div><p class="mt-1 text-xs text-muted">{{(item as any).role||(item as any).author}}</p></div></div><p class="mt-3 text-sm leading-6 text-muted">{{(item as any).desc}}</p><div v-if="(item as any).tags" class="mt-3 flex gap-1"><UBadge v-for="tag in (item as any).tags" :key="tag" color="neutral" size="xs">{{tag}}</UBadge></div><p v-if="kind==='projects'" class="mt-4 text-xs text-muted">{{(item as any).members}} {{t('common.members')}} · {{(item as any).tasks}} {{t('common.tasks')}}</p><UButton v-if="kind==='skills'||kind==='connectors'" class="mt-4 w-full" size="sm" :color="(item as any).installed||(item as any).connected?'neutral':'primary'" :variant="(item as any).installed||(item as any).connected?'outline':'solid'" :label="(item as any).installed?t('common.installed'):(item as any).connected?t('common.connected'):kind==='skills'?t('common.install'):t('common.connect')"/></UCard></component></div></div></section></template>
